{"path": "src/semver.js", "content": "// compareVersions(a, b) → -1, 0 or 1 following Semantic Versioning 2.0.0 precedence
// (including pre-release identifiers; build metadata after '+' is ignored).
export function compareVersions(a, b) {
  const va = parse(a);
  const vb = parse(b);
  for (let i = 0; i < 3; i++) {
    if (va.core[i] !== vb.core[i]) return va.core[i] < vb.core[i] ? -1 : 1;
  }
  // A version without pre-release has higher precedence than one with it.
  if (!va.pre.length && !vb.pre.length) return 0;
  if (!va.pre.length) return 1;
  if (!vb.pre.length) return -1;
  const len = Math.min(va.pre.length, vb.pre.length);
  for (let i = 0; i < len; i++) {
    const c = compareIdentifiers(va.pre[i], vb.pre[i]);
    if (c !== 0) return c;
  }
  // A larger set of pre-release fields has higher precedence when all preceding are equal.
  if (va.pre.length === vb.pre.length) return 0;
  return va.pre.length < vb.pre.length ? -1 : 1;
}

function parse(version) {
  const withoutBuild = String(version).split('+')[0];
  const dash = withoutBuild.indexOf('-');
  const core = dash === -1 ? withoutBuild : withoutBuild.slice(0, dash);
  const pre = dash === -1 ? [] : withoutBuild.slice(dash + 1).split('.');
  return { core: core.split('.').map(Number), pre };
}

const NUMERIC = /^\d+$/;

function compareIdentifiers(x, y) {
  const xNum = NUMERIC.test(x);
  const yNum = NUMERIC.test(y);
  if (xNum && yNum) {
    // Compare numerically without precision loss for long identifiers.
    const bx = BigInt(x);
    const by = BigInt(y);
    return bx === by ? 0 : bx < by ? -1 : 1;
  }
  // Numeric identifiers always have lower precedence than alphanumeric ones.
  if (xNum) return -1;
  if (yNum) return 1;
  // Alphanumeric identifiers are compared lexically in ASCII sort order.
  return x === y ? 0 : x < y ? -1 : 1;
}
"}

{"path": "test/semver.test.js", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { compareVersions } from '../src/semver.js';

test('core', () => assert.equal(compareVersions('1.2.3', '1.10.0'), -1));

test('spec precedence chain (SemVer 2.0.0 §11)', () => {
  const ordered = [
    '1.0.0-alpha',
    '1.0.0-alpha.1',
    '1.0.0-alpha.beta',
    '1.0.0-beta',
    '1.0.0-beta.2',
    '1.0.0-beta.11',
    '1.0.0-rc.1',
    '1.0.0',
  ];
  for (let i = 0; i < ordered.length; i++) {
    for (let j = 0; j < ordered.length; j++) {
      const expected = i === j ? 0 : i < j ? -1 : 1;
      assert.equal(compareVersions(ordered[i], ordered[j]), expected, `${ordered[i]} vs ${ordered[j]}`);
    }
  }
});

test('pre-release is lower than release', () => {
  assert.equal(compareVersions('1.0.0-rc.1', '1.0.0'), -1);
  assert.equal(compareVersions('1.0.0', '1.0.0-0'), 1);
});

test('core version wins over pre-release', () => {
  assert.equal(compareVersions('1.0.1-alpha', '1.0.0'), 1);
});

test('build metadata is ignored', () => {
  assert.equal(compareVersions('1.0.0+build.1', '1.0.0+build.2'), 0);
  assert.equal(compareVersions('1.0.0-alpha+001', '1.0.0-alpha'), 0);
  assert.equal(compareVersions('1.0.0-beta+exp.sha', '1.0.0-alpha'), 1);
});

test('hyphens inside pre-release identifiers', () => {
  assert.equal(compareVersions('1.0.0-x-y.1', '1.0.0-x-y.2'), -1);
});
"}
